const minutes = 5;
const boundary = minutes * 60 * 1000;
const expected = new Date(Math.floor(Date.now() / boundary) * boundary);
return [{ json: { expected_ts: expected.toISOString() } }];

// 5m derived snapshot (n8n Code node)
// Expects input shaped like: { data: [ ...rows... ] } where rows are from tv_datafeed (limit=5)

const rows = ($input.first().json.data || []).filter(Boolean);
if (!rows.length) return [{ json: { error: "No tv_datafeed rows" } }];

// Supabase returns ts DESC (newest first). Normalize to ASC for slope/momentum.
rows.sort((a, b) => Date.parse(a.ts) - Date.parse(b.ts));

const N = rows.length;
const first = rows[0];
const last = rows[N - 1];
const prev = rows[Math.max(N - 2, 0)];

const num = (x) => (x === null || x === undefined ? null : Number(x));
const r = (x) =>
  (x === null || x === undefined || Number.isNaN(Number(x)))
    ? null
    : Math.round(Number(x) * 100) / 100;

// Latest bar core values
const c = num(last.c);
const vwap = num(last.vwap);
const ema9 = num(last.ema9);
const ema21 = num(last.ema21);
const atr = num(last.atr);

const macd_last = num(last.macd_hist);
const macd_prev = num(prev.macd_hist);
const macd_first = num(first.macd_hist);

// Deltas vs value / structure
const c_minus_vwap_pts = (c != null && vwap != null) ? (c - vwap) : null;
const c_minus_ema21_pts = (c != null && ema21 != null) ? (c - ema21) : null;

// Slopes over N bars (oldest -> newest)
const first_c = num(first.c);
const last_c = num(last.c);
const first_ema9 = num(first.ema9);
const last_ema9 = num(last.ema9);
const first_ema21 = num(first.ema21);
const last_ema21 = num(last.ema21);

const c_slope_n = (last_c != null && first_c != null) ? (last_c - first_c) : null;
const ema9_slope_n = (last_ema9 != null && first_ema9 != null) ? (last_ema9 - first_ema9) : null;
const ema21_slope_n = (last_ema21 != null && first_ema21 != null) ? (last_ema21 - first_ema21) : null;

// MACD deltas
const macd_delta_1 = (macd_last != null && macd_prev != null) ? (macd_last - macd_prev) : null;
const macd_delta_n = (macd_last != null && macd_first != null) ? (macd_last - macd_first) : null;

// Rounded deltas for stable boolean logic
const macd_delta_1_r = r(macd_delta_1);
const macd_delta_n_r = r(macd_delta_n);

// Flags
const macd_falling = (macd_delta_1_r != null) ? (macd_delta_1_r < 0) : null;
const macd_below_zero = (macd_last != null) ? (macd_last < 0) : null;
const ema_bearish = (ema9 != null && ema21 != null) ? (ema9 < ema21) : null;

// Simple trend strength score (-3..+3)
const trend_score = Number(
  (ema9 != null && ema21 != null ? Math.sign(ema9 - ema21) : 0) +
  (ema9_slope_n != null ? Math.sign(ema9_slope_n) : 0) +
  (macd_delta_n_r != null ? Math.sign(macd_delta_n_r) : 0)
);

// Direction-aware “momentum improved” booleans
const momentum_improved_long =
  (macd_delta_1_r != null && macd_delta_1_r > 0) &&
  (trend_score >= 2) &&
  (ema_bearish === false);

const momentum_improved_short =
  (macd_delta_1_r != null && macd_delta_1_r < 0) &&
  (trend_score <= -2) &&
  (ema_bearish === true);

// Optional extra context (cheap + useful)
const ema_spread = (ema9 != null && ema21 != null) ? (ema9 - ema21) : null;

// Brackets (points + $) — TP $60, SL $30, sized by contract count
const POINT_VALUE_USD = 5;
const brackets = {
  1: { sl_pts: 6, tp_pts: 12 },
  2: { sl_pts: 3, tp_pts: 6 },
  3: { sl_pts: 2, tp_pts: 4 },
};

for (const k of Object.keys(brackets)) {
  const size = Number(k);
  brackets[size].sl_usd = brackets[size].sl_pts * POINT_VALUE_USD * size;
  brackets[size].tp_usd = brackets[size].tp_pts * POINT_VALUE_USD * size;
}

// ATR multiples
const atr_ok = (atr != null && atr > 0);
const tp_to_atr_size1 = atr_ok ? (brackets[1].tp_pts / atr) : null;
const sl_to_atr_size1 = atr_ok ? (brackets[1].sl_pts / atr) : null;
const tp_to_atr_size2 = atr_ok ? (brackets[2].tp_pts / atr) : null;
const sl_to_atr_size2 = atr_ok ? (brackets[2].sl_pts / atr) : null;
const tp_to_atr_size3 = atr_ok ? (brackets[3].tp_pts / atr) : null;
const sl_to_atr_size3 = atr_ok ? (brackets[3].sl_pts / atr) : null;

// 5-bar series (transparent context; oldest->newest)
const series_n = rows.map(x => ({
  ts: x.ts ?? null,
  o: num(x.o),
  h: num(x.h),
  l: num(x.l),
  c: num(x.c),
  v: num(x.v),
  ema9: num(x.ema9),
  ema21: num(x.ema21),
  vwap: num(x.vwap),
  atr: num(x.atr),
  macd_hist: num(x.macd_hist),
}));

return [{
  json: {
    // latest bar fields
    ts: last.ts,
    c,
    ema9,
    ema21,
    vwap,
    atr,
    macd_hist: macd_last,

    // continuity helpers
    momentum_improved_long,
    momentum_improved_short,

    // short history
    series_n,
    series_len: N,

    // slopes / deltas / flags
    c_slope_n: r(c_slope_n),
    ema9_slope_n: r(ema9_slope_n),
    ema21_slope_n: r(ema21_slope_n),

    macd_delta_1: macd_delta_1_r,
    macd_delta_n: macd_delta_n_r,
    macd_falling,
    macd_below_zero,

    ema_bearish,
    trend_score,
    ema_spread: r(ema_spread),

    c_minus_vwap_pts: r(c_minus_vwap_pts),
    c_minus_ema21_pts: r(c_minus_ema21_pts),

    // ATR multiples
    tp_to_atr_size1: r(tp_to_atr_size1),
    sl_to_atr_size1: r(sl_to_atr_size1),
    tp_to_atr_size2: r(tp_to_atr_size2),
    sl_to_atr_size2: r(sl_to_atr_size2),
    tp_to_atr_size3: r(tp_to_atr_size3),
    sl_to_atr_size3: r(sl_to_atr_size3),

    // bracket metadata
    point_value_usd: POINT_VALUE_USD,
    brackets,
  }
}];

const nowMs = Date.now();
const row = $input.first().json || null;

const parseTs = (t) => {
  const ms = t ? Date.parse(t) : NaN;
  return Number.isFinite(ms) ? ms : null;
};

const exit_time = row?.exit_time ?? null;
const exitMs = parseTs(exit_time);

const minutes_since_last_close =
  exitMs == null ? null : Math.round(((nowMs - exitMs) / 60000) * 10) / 10;

const pnlNum = row?.net_pnl == null ? null : Number(row.net_pnl);

let last_trade_outcome = null; // WIN | LOSS | BE | null
if (pnlNum != null && Number.isFinite(pnlNum)) {
  last_trade_outcome = pnlNum > 0 ? "WIN" : (pnlNum < 0 ? "LOSS" : "BE");
}

return [{
  json: {
    minutes_since_last_close,
    last_trade_outcome,
    last_trade_pnl: pnlNum,
    last_trade_signal: row?.signal ?? null,
    last_trade_size: row?.size ?? null,
    last_trade_ai_decision_id: row?.ai_decision_id ?? null,
  }
}];

let raw = $input.first().json.text;

// Normalize to string
raw = String(raw ?? "").trim();

// Strip code fences if present
raw = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

// Try parse directly; if it fails, extract first {...} JSON block
let obj;
try {
  obj = JSON.parse(raw);
} catch (e) {
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start >= 0 && end > start) {
    obj = JSON.parse(raw.slice(start, end + 1));
  } else {
    throw e;
  }
}

// Hardening: make reason single-line
if (typeof obj.reason === "string") {
  obj.reason = obj.reason.replace(/\r?\n|\r/g, " ").replace(/\s+/g, " ").trim();
}

// Optional: enforce size as integer
if (obj.size !== undefined) {
  obj.size = Number.parseInt(obj.size, 10);
}

// Return as a proper n8n item
return [{ json: obj }];
